/* Finite State Machine / Statechart for Unit U01_General */

/* States */
State Idle;
State Running;
State StressTest;
State BatteryLow;
State InspirationDetected;

/* Events */
Event StartClock;
Event StopClock;
Event RunAlgorithm;
Event StressTestStart;
Event StressTestEnd;
Event BatteryCheck;
Event PatientInspiration;

/* Transitions with Guards */
Transition Idle --> Running
    Guard canStartClock;

Transition Running --> StressTest
    Guard canRunAlgorithmFasterThanRealTime;

Transition StressTest --> Running
    Guard stressTestDurationExceeded;

Transition Running --> BatteryLow
    Guard batteryLevelLow;

Transition BatteryLow --> Idle
    Guard batteryRecharged;

Transition Idle --> InspirationDetected
    Guard patientInspirationDetected;

/* Guards Definitions */
Guard canStartClock
    Returns true if softwareClockRangeSufficient();

Guard canRunAlgorithmFasterThanRealTime
    Returns true if algorithmRunTime < realTimeFactor();

Guard stressTestDurationExceeded
    Returns true if stressTestDuration > twoWeeks();

Guard batteryLevelLow
    Returns true if batteryCapacity < oneHourOperation();

Guard patientInspirationDetected
    Returns true if sensorDetectsInspiration();

/* Lifecycle */
Initial Idle;

/* Additional Notes */
/* All guards must be tested for both True and False outcomes to ensure full transition coverage. */
